window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-80f0af53bc915792"]={"versions": [{"id": "FIG-80f0af53bc915792", "releases": ["R3.0.7"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation des dynamischen Verhaltens im AUTOSAR Communication Stack (Classic Platform). Dargestellt ist ein Teilablauf der Bus-Off Recovery State Machine des Moduls CanSM (CAN State Manager, System Services / Communication Management) zur Wiederinbetriebnahme der CAN-Controller über das CanIf (CAN Interface, ECU Abstraction Layer).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Lebenslinien / Module:\n<ul class=\"fig-list\"><li>«module» <code>CanSM::CanSM</code>: Steuerndes BSW-Zentralmodul für das CAN-Netzwerk- und Bus-Off-Zustandsmanagement.\n</li><li>«module» <code>CanIf::CanIf</code>: Abstraktionsschicht zur Hardwareansteuerung der CAN-Controller.\n</li></ul>\n</li><li>Interaktionsrahmen:\n<ul class=\"fig-list\"><li><code>loop</code>: Guard <code>For every CAN controller assinged to this CAN network handle</code> (Multi-Controller-Unterstützung je Netzwerk-Handle).\n</li></ul>\n</li><li>Schnittstelle / Nachricht:\n<ul class=\"fig-list\"><li><code>CanIf_SetControllerMode(CanController, ControllerMode := CANIF_CS_STARTED) : Std_ReturnType</code>: Synchroner Funktionsaufruf zur Zustandsänderung des adressierten CAN-Controllers auf <code>CANIF_CS_STARTED</code>.\n</li><li>Rückkehroperation: Asynchron bzw. synchron übermittelte Rückgabe (<code>:Std_ReturnType</code>) an CanSM via gestrichelte Pfeillinie.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Eintritt in die Restart-Phase der Bus-Off-Recovery-Zustandsmaschine des CanSM nach Ablauf relevanter Erholungszeiten.\n</li><li>Der CanSM initiiert eine Schleife (<code>loop</code>) über alle dem aktuellen Netzwerk-Handle zugewiesenen CAN-Controller.\n</li><li>Für jeden Controller sendet der CanSM synchron die Modusumschaltung <code>CanIf_SetControllerMode</code> mit dem Zielmodus <code>CANIF_CS_STARTED</code>.\n</li><li>Das CanIf verarbeitet den Aufruf und liefert den Statuswert vom Typ <code>Std_ReturnType</code> an den CanSM zurück.\n</li><li>Die Schleife wird wiederholt, bis sämtliche zugehörigen CAN-Controller neu gestartet wurden.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Normative Vorgabe für BSW-Entwickler: Beim Restart nach einem Bus-Off müssen alle physischen CAN-Controller eines logischen Netzwerk-Handles zwingend in den Zustand <code>CANIF_CS_STARTED</code> versetzt werden.\n</li><li>Fehler- und Rückgabewertbehandlung: Der Rückgabetyp <code>Std_ReturnType</code> muss vom CanSM auf <code>E_OK</code> evaluiert werden; die finale Bestätigung des Controller-Zustands erfolgt im Gesamtsystem üblicherweise über die zugehörige Callback-Indikation (<code>CanSM_ControllerModeIndication</code>).\n</li><li>Redaktionshinweis: Der Schleifenkopf enthält im Original den Tippfehler „assinged“ statt „assigned“.\n</li></ul>"}, {"id": "FIG-9b2a65e02fdee3c9", "releases": ["R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation des dynamischen Verhaltens im AUTOSAR Communication Stack (Classic Platform). Dargestellt ist ein Teilablauf der Bus-Off Recovery State Machine des Moduls CanSM (CAN State Manager, System Services / Communication Management) zur Wiederinbetriebnahme der CAN-Controller über das CanIf (CAN Interface, ECU Abstraction Layer).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Lebenslinien / Module:\n<ul class=\"fig-list\"><li>«module» <code>CanSM::CanSM</code>: Steuerndes BSW-Zentralmodul für das CAN-Netzwerk- und Bus-Off-Zustandsmanagement.\n</li><li>«module» <code>CanIf::CanIf</code>: Abstraktionsschicht zur Hardwareansteuerung der CAN-Controller.\n</li></ul>\n</li><li>Interaktionsrahmen:\n<ul class=\"fig-list\"><li><code>loop</code>: Guard <code>For every CAN controller assinged to this CAN network handle</code> (Multi-Controller-Unterstützung je Netzwerk-Handle).\n</li></ul>\n</li><li>Schnittstelle / Nachricht:\n<ul class=\"fig-list\"><li><code>CanIf_SetControllerMode(CanController, ControllerMode := CANIF_CS_STARTED) : Std_ReturnType</code>: Synchroner Funktionsaufruf zur Zustandsänderung des adressierten CAN-Controllers auf <code>CANIF_CS_STARTED</code>.\n</li><li>Rückkehroperation: Asynchron bzw. synchron übermittelte Rückgabe (<code>:Std_ReturnType</code>) an CanSM via gestrichelte Pfeillinie.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Eintritt in die Restart-Phase der Bus-Off-Recovery-Zustandsmaschine des CanSM nach Ablauf relevanter Erholungszeiten.\n</li><li>Der CanSM initiiert eine Schleife (<code>loop</code>) über alle dem aktuellen Netzwerk-Handle zugewiesenen CAN-Controller.\n</li><li>Für jeden Controller sendet der CanSM synchron die Modusumschaltung <code>CanIf_SetControllerMode</code> mit dem Zielmodus <code>CANIF_CS_STARTED</code>.\n</li><li>Das CanIf verarbeitet den Aufruf und liefert den Statuswert vom Typ <code>Std_ReturnType</code> an den CanSM zurück.\n</li><li>Die Schleife wird wiederholt, bis sämtliche zugehörigen CAN-Controller neu gestartet wurden.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Normative Vorgabe für BSW-Entwickler: Beim Restart nach einem Bus-Off müssen alle physischen CAN-Controller eines logischen Netzwerk-Handles zwingend in den Zustand <code>CANIF_CS_STARTED</code> versetzt werden.\n</li><li>Fehler- und Rückgabewertbehandlung: Der Rückgabetyp <code>Std_ReturnType</code> muss vom CanSM auf <code>E_OK</code> evaluiert werden; die finale Bestätigung des Controller-Zustands erfolgt im Gesamtsystem üblicherweise über die zugehörige Callback-Indikation (<code>CanSM_ControllerModeIndication</code>).\n</li><li>Redaktionshinweis: Der Schleifenkopf enthält im Original den Tippfehler „assinged“ statt „assigned“.\n</li></ul>"}], "trans": [{"from": "FIG-80f0af53bc915792", "to": "FIG-9b2a65e02fdee3c9", "fr": "R3.0.7", "tr": "R3.1.5", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
